mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM lambda_invoke_retry_outbox
    WHERE lambda_assignment_id = #{lambdaAssignmentId}
      AND lane = #{lane}
      AND run_id = #{runId}
      AND invocation_gen = #{invocationGen}
)

mapper.insert:
INSERT INTO lambda_invoke_retry_outbox (
    lambda_assignment_id, lane, run_id, invocation_gen, payload, retry_at
) VALUES (
    #{lambdaAssignmentId}, #{lane}, #{runId}, #{invocationGen}, #{payload}, #{retryAt}
)

mapper.update:
UPDATE lambda_invoke_retry_outbox
SET claim_until = #{claimUntil}
WHERE lambda_assignment_id = #{lambdaAssignmentId}
  AND lane = #{lane}
  AND run_id = #{runId}
  AND invocation_gen = #{invocationGen}
  AND claim_id = #{claimId,typeHandler=dev.olegz.vf.registry.dao.handlers.UuidStringTypeHandler}

mapper.delete:
DELETE FROM lambda_invoke_retry_outbox
WHERE lambda_assignment_id = #{lambdaAssignmentId}
  AND lane = #{lane}
  AND run_id = #{runId}
  AND invocation_gen = #{invocationGen}
  AND claim_id = #{claimId,typeHandler=dev.olegz.vf.registry.dao.handlers.UuidStringTypeHandler}

mapper.update:
UPDATE lambda_invoke_retry_outbox
SET claim_id = NULL, claim_until = NULL
WHERE lambda_assignment_id = #{lambdaAssignmentId}
  AND lane = #{lane}
  AND run_id = #{runId}
  AND invocation_gen = #{invocationGen}
  AND claim_id = #{claimId,typeHandler=dev.olegz.vf.registry.dao.handlers.UuidStringTypeHandler}
